<template><header class="game-toolbar"><button class="game-icon-button" type="button" :aria-label="$t('game.exit')" @click="$emit('exit')">×</button><button class="game-course-button" type="button" @click="$emit('contents')"><strong>{{ title }}</strong><span>{{ $t('game.progress', { current: current + 1, total }) }}</span></button><div class="game-toolbar-actions"><span class="game-timer">{{ time }}</span><button class="game-icon-button" type="button" :aria-label="$t('game.settings')" @click="$emit('settings')">⚙</button><button class="game-icon-button" type="button" :aria-label="$t('game.pause')" @click="$emit('pause')">Ⅱ</button></div><div class="game-progress-track"><span :style="{ width: progress }"></span></div></header></template>
<script setup lang="ts">defineProps<{ title: string; current: number; total: number; progress: string; time: string }>(); defineEmits<{ exit: []; contents: []; settings: []; pause: [] }>();</script>
